import { HtmlConf, WebViewJsParams } from "@droid/android";
import { useProxyWatch, useTranslation } from "@fanfanlo";
import { Stack, Box, TextField, Typography, Alert } from "@mui/material";
import { useState } from "react";
import { SectionTitle, RequiredLabel, OptionalLabel, WebViewConfUI } from "./WindowConfUI";
import { detectContentType } from "./data";
// WebViewJsParams UI
function WebViewJsParamsUI({ jsParams }: { jsParams: WebViewJsParams }) {
  const { t } = useTranslation('droid-android/android/win/content');
  const [fitContentWidth] = useProxyWatch(jsParams, 'fitContentWidth', jsParams.fitContentWidth || 0);
  const [fitContentHeight] = useProxyWatch(jsParams, 'fitContentHeight', jsParams.fitContentHeight || 0);
  const [javaToJsDataString] = useProxyWatch(jsParams, 'javaToJsDataString', jsParams.javaToJsDataString || '');
  const [fitContentId] = useProxyWatch(jsParams, 'fitContentId', jsParams.fitContentId || '');
  const [fitContentClass] = useProxyWatch(jsParams, 'fitContentClass', jsParams.fitContentClass || '');
  const [fitContentJs] = useProxyWatch(jsParams, 'fitContentJs', jsParams.fitContentJs || '');

  return (
    <Stack spacing={1} sx={{ pl: 2 }}>
      <TextField
        label={t('content.WebViewJsParams.fitContentWidth')}
        type="number"
        value={fitContentWidth}
        onChange={e => {
          jsParams.fitContentWidth = Number(e.target.value);
        }}
        size="small"
      />
      <TextField
        label={t('content.WebViewJsParams.fitContentHeight')}
        type="number"
        value={fitContentHeight}
        onChange={e => {
          jsParams.fitContentHeight = Number(e.target.value);
        }}
        size="small"
      />
      <TextField
        label={t('content.WebViewJsParams.javaToJsDataString')}
        value={javaToJsDataString}
        onChange={e => {
          jsParams.javaToJsDataString = e.target.value;
        }}
        size="small"
        multiline
        rows={2}
      />
      <TextField
        label={t('content.WebViewJsParams.fitContentId')}
        value={fitContentId}
        onChange={e => {
          jsParams.fitContentId = e.target.value;
        }}
        size="small"
      />
      <TextField
        label={t('content.WebViewJsParams.fitContentClass')}
        value={fitContentClass}
        onChange={e => {
          jsParams.fitContentClass = e.target.value;
        }}
        size="small"
      />
      <TextField
        label={t('content.WebViewJsParams.fitContentJs')}
        value={fitContentJs}
        onChange={e => {
          jsParams.fitContentJs = e.target.value;
        }}
        size="small"
        multiline
        rows={2}
      />
    </Stack>
  );
}

export function HtmlConfUI({ htmlConf }: { htmlConf: HtmlConf }) {
  const { t } = useTranslation('droid-android/android/win/content');
  const [url] = useProxyWatch(htmlConf, 'url', htmlConf.url || '');
  const [html] = useProxyWatch(htmlConf, 'html', htmlConf.html || '');
  const [jsBridgeName] = useProxyWatch(htmlConf, 'jsBridgeName', htmlConf.jsBridgeName || '');
  const [webViewJsParams] = useProxyWatch(htmlConf, 'webViewJsParams', htmlConf.webViewJsParams);
  const [webViewConf] = useProxyWatch(htmlConf, 'webViewConf', htmlConf.webViewConf);
  const [webViewJsName] = useProxyWatch(htmlConf, 'webViewJsName', htmlConf.webViewJsName || '');
  const [javaRunnerId] = useProxyWatch(htmlConf, 'javaRunnerId', htmlConf.javaRunnerId || 0);
  const [extra] = useProxyWatch(htmlConf, 'extra', htmlConf.extra || {});

  // 本地状态用于内容输入和错误提示
  const [contentInput, setContentInput] = useState(htmlConf.url || htmlConf.html || '');
  const [contentError, setContentError] = useState('');
  const [detectedType, setDetectedType] = useState<'url' | 'html' | 'invalid'>('invalid');

  // 本地状态用于 JSON 编辑和错误提示
  const [extraJson, setExtraJson] = useState(JSON.stringify(htmlConf.extra || {}, null, 2));
  const [extraJsonError, setExtraJsonError] = useState('');

  const handleContentChange = (value: string) => {
    console.log('HtmlConfUI: content input changed');
    setContentInput(value);

    if (!value || value.trim().length === 0) {
      setDetectedType('invalid');
      setContentError('');
      htmlConf.url = '';
      htmlConf.html = '';
      return;
    }

    const type = detectContentType(value);
    console.log('HtmlConfUI: detected content type:', type);
    setDetectedType(type);

    if (type === 'invalid') {
      setContentError(t('content.HtmlConf.contentInvalid'));
      return;
    }

    setContentError('');

    if (type === 'url') {
      htmlConf.url = value;
      htmlConf.html = '';
      console.log('HtmlConfUI: set as URL:', value);
    } else if (type === 'html') {
      htmlConf.html = value;
      htmlConf.url = '';
      console.log('HtmlConfUI: set as HTML:', value);
    }
  };

  const extraJsonChange = (value: string) => {
    console.log('HtmlConfUI: extra JSON changed');
    setExtraJson(value);
    try {
      const parsed = JSON.parse(value);
      htmlConf.extra = parsed;
      setExtraJsonError('');
      console.log('HtmlConfUI: extra JSON parsed successfully:', parsed);
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : '无效的 JSON 格式';
      setExtraJsonError(errorMsg);
      console.error('HtmlConfUI: extra JSON parse error:', err);
    }
  };

  return (
    <Stack spacing={2}>
      {/* 必选属性部分 */}
      <SectionTitle title={t('content.HtmlConf.required')} count={1} />

      {/* 统一的内容输入框 - 自动检测 URL 或 HTML */}
      <Box>
        <RequiredLabel label={t('content.HtmlConf.content')} />
        {contentError && (
          <Alert severity="error" sx={{ mb: 1 }}>
            {contentError}
          </Alert>
        )}
        {detectedType !== 'invalid' && (
          <Alert severity="success" sx={{ mb: 1 }}>
            {t('content.HtmlConf.detectedAs')}: {detectedType === 'url' ? 'URL' : 'HTML'}
          </Alert>
        )}
        <TextField
          value={contentInput}
          onChange={e => handleContentChange(e.target.value)}
          placeholder={t('content.HtmlConf.contentPlaceholder')}
          size="small"
          multiline
          rows={4}
          fullWidth
          helperText={t('content.HtmlConf.contentHelper')}
          error={!!contentError}
        />
      </Box>

      {/* 可选属性部分 */}
      <SectionTitle title={t('content.HtmlConf.optional')} count={6} />

      <Box>
        <OptionalLabel label={t('content.HtmlConf.jsBridgeName')} />
        <TextField
          value={jsBridgeName}
          onChange={e => {
            htmlConf.jsBridgeName = e.target.value;
          }}
          size="small"
          fullWidth
        />
      </Box>

      <Box>
        <OptionalLabel label={t('content.HtmlConf.webViewJsName')} />
        <TextField
          value={webViewJsName}
          onChange={e => {
            htmlConf.webViewJsName = e.target.value;
          }}
          size="small"
          fullWidth
        />
      </Box>

      <Box>
        <OptionalLabel label={t('content.HtmlConf.javaRunnerId')} />
        <TextField
          type="number"
          value={javaRunnerId}
          onChange={e => {
            htmlConf.javaRunnerId = Number(e.target.value);
          }}
          size="small"
          fullWidth
        />
      </Box>

      {webViewJsParams && (
        <>
          <Typography variant="subtitle2">{t('content.WebViewJsParams.title')}</Typography>
          <WebViewJsParamsUI jsParams={webViewJsParams} />
        </>
      )}

      {webViewConf && (
        <>
          <Typography variant="subtitle2">{t('content.WebViewConf.title')}</Typography>
          <WebViewConfUI webViewConf={webViewConf} />
        </>
      )}

      {/* Extra 配置 - JSON 编辑器 */}
      <Box>
        <OptionalLabel label={t('content.HtmlConf.extra')} />
        {extraJsonError && (
          <Alert severity="error" sx={{ mb: 1 }}>
            {t('content.HtmlConf.extraJsonError')}: {extraJsonError}
          </Alert>
        )}
        <TextField
          value={extraJson}
          onChange={e => extraJsonChange(e.target.value)}
          placeholder={t('content.HtmlConf.extraPlaceholder')}
          size="small"
          multiline
          rows={4}
          fullWidth
          helperText={t('content.HtmlConf.extraHelper')}
          error={!!extraJsonError}
        />
      </Box>
    </Stack>
  );
}